-- Complete, standalone, idempotent demo seed for TenderCraft Evaluate.
--
-- **Why this exists.** `docs/evaluate/DEMO.md` told an operator to reset by running
-- `0002_seed.sql`, and that command cannot work: 0002 inserts into `evaluations` with
-- `evaluation_id` columns, both of which `0003_rename.sql` renamed. It is correct IN THE CHAIN
-- (0001 creates, 0002 seeds, 0003 renames) and fails the moment it is run on its own — which is
-- exactly what the reset instruction asked for. 0002 also never seeded the committee, the
-- scores, the second tender or the COI declarations; those were loaded out of band and existed
-- nowhere in the repository, so the demo could not be rebuilt from source at all.
--
-- This file can be run at any time against the current schema and leaves the demo in the state
-- the walkthrough describes.
--
-- **Upserts, never deletes.** `audit_events` is append-only and its trigger refuses a delete
-- even to the service role, so a cascade from `delete from tenders` is refused and the whole
-- reset would fail (docs/evaluate/known-pitfalls.md). Every statement below is
-- `on conflict (id) do update`, which keeps ids stable, keeps the audit trail intact — an audit
-- trail a reset can wipe is not an audit trail — and makes re-running this a no-op.
--
-- **What it does not create:** the auth users themselves. `authority_members.user_id` and
-- `profiles.user_id` reference accounts in Supabase Auth (officer@pmc.test and friends), which
-- this file cannot create. Reset restores the DATA on top of existing accounts; standing up a
-- brand-new project needs those users created first.
--
-- Generated from the live demo database on 2026-08-01, after 0005 corrected the AI-deference
-- fixture — so the `ai_proposed_mark` values here are already the corrected ones and 0005 is a
-- no-op against this seed.

begin;

-- ── authorities ──
-- the two authorities — A stays EMPTY on purpose (PRD §10): journey ACs run there,
-- and a first-run AC proved against seeded data proves nothing
on conflict (id) do update set name = excluded.name, created_at = excluded.created_at;

-- ── profiles ──
-- which authority each demo account lands in
on conflict (user_id) do update set email = excluded.email, active_authority_id = excluded.active_authority_id;

-- ── authority_members ──
-- the committee. Roles here drive every permission check and the report's attribution
on conflict (id) do update set authority_id = excluded.authority_id, user_id = excluded.user_id, email = excluded.email, full_name = excluded.full_name, role = excluded.role, created_at = excluded.created_at;

-- ── tenders ──
-- three active tenders: one mid-evaluation, one concluded, one in screening
on conflict (id) do update set authority_id = excluded.authority_id, title = excluded.title, tender_number = excluded.tender_number, state = excluded.state, technical_weight = excluded.technical_weight, financial_weight = excluded.financial_weight, qualifying_marks = excluded.qualifying_marks, tie_break_rule = excluded.tie_break_rule, quorum = excluded.quorum, framework_locked_at = excluded.framework_locked_at, framework_locked_by = excluded.framework_locked_by, technical_locked_at = excluded.technical_locked_at, technical_locked_by = excluded.technical_locked_by, created_at = excluded.created_at;

-- ── criteria ──
-- published criteria — PQ ones carry a comparison so screening is arithmetic, not opinion
on conflict (id) do update set authority_id = excluded.authority_id, tender_id = excluded.tender_id, kind = excluded.kind, text = excluded.text, max_marks = excluded.max_marks, compare_kind = excluded.compare_kind, compare_op = excluded.compare_op, compare_value = excluded.compare_value, anchor_page = excluded.anchor_page, anchor_clause = excluded.anchor_clause, confidence = excluded.confidence, confirmed = excluded.confirmed, order_index = excluded.order_index;

-- ── bids ──
-- the bids, with their responsiveness verdicts and recorded reasons
on conflict (id) do update set authority_id = excluded.authority_id, tender_id = excluded.tender_id, bidder_name = excluded.bidder_name, responsive = excluded.responsive, responsive_reason = excluded.responsive_reason, screened_by = excluded.screened_by, created_at = excluded.created_at;

-- ── bid_responses ──
-- what each bid stated against each criterion, with page anchors
on conflict (id) do update set authority_id = excluded.authority_id, bid_id = excluded.bid_id, criterion_id = excluded.criterion_id, stated_value = excluded.stated_value, excerpt = excluded.excerpt, anchor_page = excluded.anchor_page;

-- ── bid_financials ──
-- sealed prices. Present from ingest, unreadable through any API until technical lock
on conflict (id) do update set authority_id = excluded.authority_id, bid_id = excluded.bid_id, amount_inr = excluded.amount_inr, opened_at = excluded.opened_at, opened_by = excluded.opened_by;

-- ── scores ──
-- individual marks. pre_reveal_mark is what makes the deference metric (F7-AC5) computable
on conflict (id) do update set authority_id = excluded.authority_id, tender_id = excluded.tender_id, bid_id = excluded.bid_id, criterion_id = excluded.criterion_id, evaluator_id = excluded.evaluator_id, pre_reveal_mark = excluded.pre_reveal_mark, ai_proposed_mark = excluded.ai_proposed_mark, final_mark = excluded.final_mark, rationale = excluded.rationale, amended_after_reveal = excluded.amended_after_reveal, submitted_at = excluded.submitted_at;

-- ── coi_declarations ──
-- conflict-of-interest declarations, including the chair's — it appears in the report
on conflict (id) do update set authority_id = excluded.authority_id, tender_id = excluded.tender_id, user_id = excluded.user_id, has_interest = excluded.has_interest, detail = excluded.detail, filed_at = excluded.filed_at;

-- ── drafts ──
-- the deliberately-bad draft the TP1 walkthrough opens with
on conflict (id) do update set authority_id = excluded.authority_id, title = excluded.title, tender_number = excluded.tender_number, category = excluded.category, scope = excluded.scope, estimated_value = excluded.estimated_value, estimated_annual_value = excluded.estimated_annual_value, submission_window_days = excluded.submission_window_days, bid_structure = excluded.bid_structure, emd_amount = excluded.emd_amount, emd_exemption_stated = excluded.emd_exemption_stated, pre_bid_meeting_at = excluded.pre_bid_meeting_at, pre_bid_days_before_deadline = excluded.pre_bid_days_before_deadline, technical_weight = excluded.technical_weight, financial_weight = excluded.financial_weight, qualifying_marks = excluded.qualifying_marks, quorum = excluded.quorum, state = excluded.state, rulepack_version = excluded.rulepack_version, published_tender_id = excluded.published_tender_id, published_at = excluded.published_at, created_by = excluded.created_by, created_at = excluded.created_at, updated_at = excluded.updated_at;

-- A reset that silently produced an empty demo would be discovered on stage. Fail loudly here.
do $$
declare n_scores int; n_active int; n_members int;
begin
  select count(*) into n_scores from scores;
  select count(*) into n_active from tenders where state = 'active';
  select count(*) into n_members from authority_members;
  raise notice 'seed: % active tenders, % committee members, % individual marks',
    n_active, n_members, n_scores;
  if n_scores < 60 or n_active < 3 or n_members < 4 then
    raise exception 'demo seed incomplete: % tenders, % members, % scores', n_active, n_members, n_scores;
  end if;
end $$;

commit;
